% This test file was generated by Copilot. Validate generated output before use.
classdef TestCleanFlightData < matlab.unittest.TestCase
    methods(Test)
        function testRemovesGroundRowsAndCleansSensorDropouts(testCase)
            % Verify ground samples are removed and sensor outliers are filled.
            rawData = table;

            rawData.TrueAirSpeed = [20; 25; 120*ones(120,1)];
            rawData.Altitude = [50; 80; 1000*ones(120,1)];
            rawData.OilPressure = [90; 95; 80*ones(120,1)];
            rawData.OilTemperature = [30; 35; 25*ones(120,1)];

            rawData.OilPressure(60+2) = 200;
            rawData.OilPressure(70+2) = 20;
            rawData.OilTemperature(80+2) = 300;
            rawData.OilTemperature(90+2) = -100;

            [cleanData, summary] = cleanFlightData(rawData);

            testCase.verifyEqual(height(cleanData), 120);
            testCase.verifyEqual(summary.RawRows, 122);
            testCase.verifyEqual(summary.FlightRows, 120);
            testCase.verifyEqual(summary.GroundRowsRemoved, 2);
            testCase.verifyEqual(summary.PressureSamplesCleaned, 2);
            testCase.verifyEqual(summary.TemperatureSamplesCleaned, 2);
            testCase.verifyEqual(summary.TotalSamplesCleaned, 4);

            testCase.verifyEqual(cleanData.OilPressure(60), 80, "AbsTol", 1e-12);
            testCase.verifyEqual(cleanData.OilPressure(70), 80, "AbsTol", 1e-12);
            testCase.verifyEqual(cleanData.OilTemperature(80), 25, "AbsTol", 1e-12);
            testCase.verifyEqual(cleanData.OilTemperature(90), 25, "AbsTol", 1e-12);
        end

        function testPreservesAlreadyCleanFlightData(testCase)
            % Verify clean flight data passes through unchanged.
            rawData = table;

            rawData.TrueAirSpeed = repmat(140, 10, 1);
            rawData.Altitude = repmat(12000, 10, 1);
            rawData.OilPressure = repmat(85, 10, 1);
            rawData.OilTemperature = repmat(40, 10, 1);

            [cleanData, summary] = cleanFlightData(rawData);

            testCase.verifyEqual(cleanData, rawData);
            testCase.verifyEqual(summary.RawRows, 10);
            testCase.verifyEqual(summary.FlightRows, 10);
            testCase.verifyEqual(summary.GroundRowsRemoved, 0);
            testCase.verifyEqual(summary.PressureSamplesCleaned, 0);
            testCase.verifyEqual(summary.TemperatureSamplesCleaned, 0);
            testCase.verifyEqual(summary.TotalSamplesCleaned, 0);
        end

        function testRemovesAllGroundRows(testCase)
            % Verify the function returns an empty table when all samples are ground data.
            rawData = table;

            rawData.TrueAirSpeed = [10; 20; 30];
            rawData.Altitude = [0; 50; 90];
            rawData.OilPressure = [70; 75; 80];
            rawData.OilTemperature = [20; 21; 22];

            [cleanData, summary] = cleanFlightData(rawData);

            testCase.verifyEmpty(cleanData);
            testCase.verifyEqual(summary.RawRows, 3);
            testCase.verifyEqual(summary.FlightRows, 0);
            testCase.verifyEqual(summary.GroundRowsRemoved, 3);
            testCase.verifyEqual(summary.PressureSamplesCleaned, 0);
            testCase.verifyEqual(summary.TemperatureSamplesCleaned, 0);
            testCase.verifyEqual(summary.TotalSamplesCleaned, 0);
        end
    end
end